"""Publishes a generated document to BookStack. Worker thread only; no widgets."""

import json
import logging
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path

from generation.renderers import PreparedDocument, substitute_tokens
from publish import tags as tag_vocab
from publish.bookstack_client import BookStackClient, BookStackError
from publish.token import load_token

log = logging.getLogger(__name__)

_BOOK_DESCRIPTION = (
    "Documentation generated by AutoDoc from screen recordings. "
    "Holding book — pages are drafts pending review and filing."
)


@dataclass
class PublishResult:
    """Outcome of one publish attempt. `skipped` is not a failure."""

    ok: bool = False
    skipped: bool = False
    reason: str = ""
    page_url: str = ""
    page_id: int | None = None
    uploaded: int = 0
    state: dict = field(default_factory=dict)


def publish_session(
    config,
    session_dir: Path,
    session_data: dict,
    prepared: PreparedDocument,
) -> PublishResult:
    """Publish to BookStack, recording the outcome in session.json. Never raises."""
    if not getattr(config, "bookstack_enabled", False):
        return PublishResult(skipped=True, reason="disabled in settings")

    token = load_token()
    if token is None:
        return PublishResult(skipped=True, reason="no BookStack token available")

    # Mutated in place by _publish: failure paths need the page id, else retries duplicate.
    state = dict(session_data.get("bookstack") or {})

    try:
        client = BookStackClient(
            base_url=config.bookstack_base_url,
            token_id=token[0],
            token_secret=token[1],
            timeout_s=getattr(config, "bookstack_timeout_s", 30),
        )
        result = _publish(client, config, session_data, prepared, state)
    except BookStackError as exc:
        return _fail(session_dir, state, str(exc))
    except Exception as exc:                                    # noqa: BLE001
        log.exception("bookstack: unexpected publish failure")
        return _fail(session_dir, state, repr(exc))

    _write_state(session_dir, result.state)
    log.info(
        "bookstack: published page %s (%d image(s)) → %s",
        result.page_id,
        result.uploaded,
        result.page_url,
    )
    return result


def _publish(
    client: BookStackClient,
    config,
    session_data: dict,
    prepared: PreparedDocument,
    state: dict,
) -> PublishResult:
    # The API forces this order: the page must exist before images can attach to it.
    title = _page_title(session_data, prepared)
    payload_tags = tag_vocab.build_tags(
        doc_type=getattr(config, "bookstack_tag_doc_type", "sop"),
        owner=getattr(config, "bookstack_tag_owner", "it-ops"),
        audience=getattr(config, "bookstack_tag_audience", "all-staff"),
        review_cycle=getattr(config, "bookstack_tag_review_cycle", "ad-hoc"),
    )

    page_id = state.get("page_id")
    if page_id is not None and not _page_exists(client, page_id):
        log.warning("bookstack: page %s no longer exists — creating a new one", page_id)
        page_id = None
        state.clear()

    placeholder = substitute_tokens(prepared.doc, lambda _eid: "")

    if page_id is None:
        book_id = client.ensure_book(config.bookstack_book, _BOOK_DESCRIPTION)
        page = client.create_page(
            book_id=book_id, name=title, markdown=placeholder, tags=payload_tags
        )
        page_id = int(page["id"])
        state.clear()
        state.update({"page_id": page_id, "book_id": book_id, "image_ids": []})
        log.info("bookstack: created page %s (%r)", page_id, title)

    # Delete first, so a republish can't leave both generations' images attached.
    _delete_images(client, state.get("image_ids") or [])
    state["image_ids"] = []

    urls: dict[str, str] = {}
    image_ids: list[int] = []
    for event_id, path in prepared.images.items():
        try:
            record = client.upload_image(
                page_id, Path(path), name=f"{title} - {event_id}"
            )
        except BookStackError as exc:
            if exc.status == 403:
                raise BookStackError(
                    "image upload was refused (HTTP 403). BookStack requires BOTH "
                    "'Images: Create All' AND page-update permission on the target "
                    "page — uploading a gallery image counts as updating the page "
                    "it attaches to. Grant the bot role Pages: Update (Own is "
                    "enough, since the bot authors these pages).\n\n"
                    f"Original error: {exc}",
                    status=403,
                ) from exc
            raise
        url = _image_url(record, client.base_url)
        if not url:
            raise BookStackError(
                f"image upload for {event_id} returned no usable URL: "
                f"{sorted(record)}"
            )
        urls[event_id] = url
        if record.get("id") is not None:
            image_ids.append(int(record["id"]))
        # Recorded as we go so a retry can clean up whatever did upload.
        state["image_ids"] = list(image_ids)

    final = substitute_tokens(
        prepared.doc,
        lambda eid: f"![Screenshot {eid}]({urls[eid]})" if eid in urls else "",
    )
    page = client.update_page(page_id, markdown=final, name=title, tags=payload_tags)

    page_url = page.get("url") or f"{client.base_url}/books/{state.get('book_id')}"
    state.update(
        {
            "page_id": page_id,
            "page_url": page_url,
            "last_pushed": datetime.now().isoformat(timespec="seconds"),
            "status": "ok",
            "error": "",
        }
    )
    return PublishResult(
        ok=True,
        page_url=page_url,
        page_id=page_id,
        uploaded=len(urls),
        state=state,
    )


def _page_title(session_data: dict, prepared: PreparedDocument) -> str:
    """The document's H1, falling back to the session name."""
    title = (prepared.title or "").strip()
    if not title:
        title = (
            session_data.get("name")
            or session_data.get("session_id")
            or "Untitled AutoDoc page"
        )
    return title[:255]


def _page_exists(client: BookStackClient, page_id: int) -> bool:
    try:
        client.get_page(page_id)
        return True
    except BookStackError as exc:
        if exc.status == 404:
            return False
        raise


def _image_url(record: dict, base_url: str) -> str:
    """Absolute display URL for an image-gallery record; the field name varies by
    BookStack version, and a relative URL would resolve against the page's own URL."""
    candidate = record.get("url") or record.get("path") or ""
    if not candidate:
        thumbs = record.get("thumbs") or {}
        candidate = thumbs.get("display") or thumbs.get("gallery") or ""
    if candidate and not candidate.startswith(("http://", "https://")):
        candidate = f"{base_url}/{candidate.lstrip('/')}"
    return candidate


def _delete_images(client: BookStackClient, image_ids: list) -> None:
    """Remove a previous generation's gallery images. Failures are logged only."""
    for image_id in image_ids:
        try:
            client.delete_image(int(image_id))
        except (BookStackError, ValueError, TypeError) as exc:
            log.warning("bookstack: could not delete old image %s: %s", image_id, exc)


def _fail(session_dir: Path, state: dict, error: str) -> PublishResult:
    """Record a failed attempt, keeping the page id so a retry adopts that page."""
    state = dict(state)
    state["status"] = "failed"
    state["error"] = error[:1000]
    state["last_attempt"] = datetime.now().isoformat(timespec="seconds")
    _write_state(session_dir, state)
    log.error("bookstack: publish failed: %s", error)
    return PublishResult(
        ok=False, reason=error, page_id=state.get("page_id"), state=state
    )


def _write_state(session_dir: Path, state: dict) -> None:
    """Merge `state` into session.json's "bookstack" key, atomically; never raises.
    Re-reads from disk so edits saved during generation are not clobbered."""
    path = session_dir / "session.json"
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        data["bookstack"] = state
        tmp = path.with_suffix(".json.tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        tmp.replace(path)
    except (OSError, json.JSONDecodeError) as exc:
        log.warning("bookstack: could not record publish state in %s: %s", path, exc)
